function swapAdjectives(sentence) {
  const words = sentence.split(' ');
  const adjectiveIndices = []; // Track positions of adjectives

  for (let i = 0; i < words.length; i++) {
    if (isAdjective(words[i])) {  // Assuming a simple adjective detection method (can be refined)
      adjectiveIndices.push(i);
    }
  }

  if (adjectiveIndices.length >= 2) {  // Ensure at least two adjectives exist for swapping
    const [firstAdjIndex, secondAdjIndex] = adjectiveIndices.slice(0, 2);
    [words[firstAdjIndex], words[secondAdjIndex]] = [words[secondAdjIndex], words[firstAdjIndex]]; 
  }

  return words.join(' ');
}

// Simple adjective detection (expand for more robust handling)
function isAdjective(word) {
  // Basic rule: Check common adjective endings (modify for accuracy)
  return word.endsWith('ful') || word.endsWith('able') || word.match(/^[a-z]+(?:-?[a-z]+)?$/i); 
}

// Example usage:
const originalSentence = "Beautiful green trees are in the park";
const modifiedSentence = swapAdjectives(originalSentence);
console.log(modifiedSentence); // Output: Green beautiful trees are in the park 
```

